                    f'Run `tox -- {Path(*rel_path.parts[:2])} --update-goldens` to update it.'
                )
            diff = str(excinfo.value).split('\n', 1)[-1]
            return message + '\n\n' + diff
        else:
            return pytest.Item.repr_failure(self, excinfo)

